// src/commands/package.ts
function registerPackage(program3, g3) {
  program3.command("narrate").description('Edge TTS narration per lesson + "Hear the plan" -> audio/, crew/narration.json').option("--lessons <keys>", "only these lessons, comma-separated").option("--voice <id>", "Edge voice, e.g. en-US-AvaMultilingualNeural").option("--langs <codes>", "languages for speaking drills, e.g. en,ms").action((o2) => runCommand("narrate", g3(), (ctx) => narrate(ctx, {
    lessons: o2.lessons ? csv(o2.lessons) : void 0,
    voice: o2.voice,
    langs: o2.langs ? csv(o2.langs) : void 0
  }), { args: argSummary(o2) }));
  program3.command("export").description("review schedule, lessons/*.md (Obsidian), deck.csv (Anki), reviews.ics, REPORT.md").action(() => runCommand("export", g3(), (ctx) => exportAll(ctx)));
  program3.command("build").description("assemble + validate course.json and paste it into the player -> index.html").option("--template <html>", "player template (default: the skill's templates/player.html)").action((o2) => runCommand("build", g3(), (ctx) => {
    const template2 = findTemplate(o2.template);
    if (!template2) {
      throw new BilimindError(
        o2.template ? `Template not found: ${o2.template}` : "The player template is missing.",
        `Expected one of: ${templateCandidates().join(" | ")}. Reinstall the skill (templates/player.html).`
      );
    }
    return build(ctx, { template: template2 });
  }, { args: argSummary(o2) }));
  program3.command("due").description("(P2) pick due review questions -> review/today.html").option("--n <n>", "how many", "3").action((o2) => runCommand("due", g3(), (ctx) => due(ctx, { n: int2(o2.n, "--n", 1, 50) }), { args: argSummary(o2) }));
  program3.command("grade").description("(P2) grade typed answers to the last `due`, reschedule, refresh reviews.ics").requiredOption("--answers <reply>", 'e.g. "1 b, 2 chaining, 3 O(n)"').action((o2) => runCommand("grade", g3(), (ctx) => grade(ctx, { answers: o2.answers }), { args: argSummary(o2) }));
  program3.command("plant").description("(benchmark) flip N answer keys in a COPY of a course, record them in a hidden key").option("--lesson <key>", "only this lesson").option("--n <n>", "how many errors to plant", "10").action((o2) => runCommand("plant", g3(), (ctx) => plant(ctx, { lesson: o2.lesson, n: int2(o2.n, "--n", 1, 200) }), { args: argSummary(o2), lesson: o2.lesson }));
  program3.command("plant-score").description("(benchmark) score the Checker's verdicts against the planted key").action(() => runCommand("plant-score", g3(), (ctx) => plantScore(ctx)));
  program3.command("run").description("(builders only) the whole pipeline without agents: fixtures, regression, cost").requiredOption("--src <folder>", "source folder").requiredOption("--sentence <text>", "the user's request").option("--slug <slug>", "course folder name").option("--out <dir>", "output root (default: ./bilimind-out)").option("--concurrency <n>", "parallel lesson drafts", "4").option("--max-lessons <n>", "most lessons to keep", "6").option("--repair-rounds <n>", "re-draft rounds for lessons that fail checks", "1").option("--no-narrate", "skip Edge TTS").option("--template <html>", "player template").action((o2) => runCommand("run", g3(), async (ctx) => {
    const gl = g3();
    const template2 = findTemplate(o2.template);
    const d2 = await runPipeline({
      src: o2.src,
      sentence: o2.sentence,
      slug: o2.slug,
      outRoot: o2.out,
      noCache: gl.cache === false,
      concurrency: int2(o2.concurrency, "--concurrency", 1, 12),
      maxLessons: int2(o2.maxLessons, "--max-lessons", 1, 20),
      repairRounds: int2(o2.repairRounds, "--repair-rounds", 0, 3),
      narrate: o2.narrate,
      template: template2,
      model: gl.model,
      maxUsd: maxUsdOf(gl)
    });
    ctx.spend.usd = d2.cost_usd;
    return d2;
  }, { needsCourse: false, args: argSummary({ src: o2.src, slug: o2.slug, concurrency: o2.concurrency }) }));
}

// src/main.ts
for (const k2 of ["log", "info", "debug"]) console[k2] = (...a2) => {
  process.stderr.write(format(...a2) + "\n");
};
exportLocations();
var program2 = new Command("bilimind").description("BiliMind for WorkBuddy: one sentence in, a course out, checked against your slides.").option("--course <dir>", "course folder (default: newest under ./bilimind-out/)").option("--as <agent>", 'agent label for the log, e.g. "Writer \xB7 Hashing"', "Lead").option("--no-cache", "skip the LLM response cache (every rehearsal and stage run)").option("--model <id>", "model override").option("--max-usd <n>", "refuse a command that would spend more than this").showHelpAfterError(false).configureOutput({ writeOut: (s6) => process.stderr.write(s6), writeErr: (s6) => process.stderr.write(s6) }).exitOverride();
var g2 = () => program2.opts();
registerSetup(program2, g2);
registerPlanning(program2, g2);
registerLessons(program2, g2);
registerChecker(program2, g2);
registerPackage(program2, g2);
for (const c2 of program2.commands) c2.exitOverride().configureOutput({ writeOut: (s6) => process.stderr.write(s6), writeErr: (s6) => process.stderr.write(s6) });
var KNOWN = new Set(program2.commands.map((c2) => c2.name()));
var argv = process.argv.slice(2);
var cmdName = argv.find((a2) => KNOWN.has(a2)) ?? argv.find((a2) => !a2.startsWith("-")) ?? "";
try {
  if (!argv.length) {
    program2.outputHelp();
    emit({ ok: false, cmd: "", error: "No command given.", hint: 'Start with `doctor`, then `init --src <folder> --sentence "<text>"`.' });
    process.exitCode = 1;
  } else {
    await program2.parseAsync(process.argv);
  }
} catch (e2) {
  const code2 = e2 instanceof CommanderError ? e2.code : "";
  if (/helpDisplayed|commander\.help$|version/.test(code2)) {
  } else if (!hasEmitted()) {
    const msg = oneLine((e2 instanceof Error ? e2.message : String(e2)).replace(/^error: /, ""));
    emit({ ok: false, cmd: cmdName, error: msg, hint: KNOWN.has(cmdName) ? `Run \`${cmdName} --help\` to see its flags.` : "Run `--help` to see the commands." });
    process.exitCode = 1;
  }
}
setTimeout(() => process.exit(), 1500).unref();
export {
  program2 as program
};
